package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_hasAttr_TriageGen0Test {

    @Test
    public void testHasAttr_NullAttributeKey() {
        Node node = Jsoup.parse("<div></div>").body().childNode(0);
        assertNull(node.hasAttr(null));
    }

    @Test
    public void testHasAttr_EmptyAttributeKey() {
        Node node = Jsoup.parse("<div attr=\"\"></div>").body().childNode(0);
        assertFalse(node.hasAttr(""));
    }

    @Test
    public void testHasAttr_NoAttribute() {
        Node node = Jsoup.parse("<div></div>").body().childNode(0);
        assertFalse(node.hasAttr("non-existent-attribute"));
    }

    @Test
    public void testHasAttr_ExistingAttribute() {
        Node node = Jsoup.parse("<div attr=\"value\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("attr"));
    }

    @Test
    public void testHasAttr_CustomAttributes() {
        Node node = Jsoup.parse("<div custom-attribute=\"value\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("custom-attribute"));
    }

    @Test
    public void testHasAttr_UppercaseAttributeKey() {
        Node node = Jsoup.parse("<div attr=\"value\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("ATTR"));
    }

    @Test
    public void testHasAttr_MultipleAttributes() {
        Node node = Jsoup.parse("<div attr1=\"value1\" attr2=\"value2\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("attr1"));
        assertTrue(node.hasAttr("attr2"));
    }

    @Test
    public void testHasAttr_AttributeWithSpaces() {
        Node node = Jsoup.parse("<div attr  \" value\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("attr "));
    }

    @Test
    public void testHasAttr_AttributeWithSpecialChars() {
        Node node = Jsoup.parse("<div attr:1=\"value\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("attr:1"));
    }

    @Test
    public void testHasAttr_AttributeWithQuotes() {
        Node node = Jsoup.parse("<div attr=\"value\" attr2=\"value2\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("attr"));
    }

    @Test
    public void testHasAttr_AttributeWithDots() {
        Node node = Jsoup.parse("<div attr.1=\"value\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("attr.1"));
    }

    @Test
    public void testHasAttr_AttributeWithHyphens() {
        Node node = Jsoup.parse("<div attr-1=\"value\"></div>").body().childNode(0);
        assertTrue(node.hasAttr("attr-1"));
    }
}
